const raw=$json.body ?? $json;
const seeds=(raw.seed_companies ?? raw.best_fit_companies ?? []).map((s)=>{
  if(typeof s==='string') return {name:s,domain:s};
  return {name:s.name ?? s.company ?? s.domain,domain:s.domain ?? s.website ?? ''};
}).map((s)=>({...s,domain:String(s.domain).toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0]})).filter((s)=>s.domain);
const icp=typeof raw.icp==='string'?{definition:raw.icp}:raw.icp;
const missing=[];
if(!icp?.definition) missing.push('icp.definition');
if(!seeds.length) missing.push('seed_companies');
if(!(raw.target_titles ?? []).length) missing.push('target_titles');
if(!raw.offer) missing.push('offer');
if(missing.length) throw new Error('Missing required intake fields: '+missing.join(', '));
return [{json:{
  run_id:raw.run_id ?? ('ai-sdr-'+Date.now()),
  dry_run:raw.dry_run===true,
  campaign_name:raw.campaign_name ?? 'AI SDR campaign',
  icp,
  seeds,
  geography:raw.geography ?? '',
  employee_min:Number(raw.employee_min ?? 1),
  employee_max:Number(raw.employee_max ?? 100000),
  target_titles:raw.target_titles,
  target_seniorities:raw.target_seniorities ?? ['Founder/Owner','C-Suite','Partner','Vice President','Head','Director'],
  offer:raw.offer,
  voice_rules:raw.voice_rules ?? 'Use only supplied facts. Keep messages concise.',
  approved_sequence:raw.approved_sequence ?? null,
  excluded_domains:(raw.excluded_domains ?? []).map((d)=>String(d).toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0]),
  lookalike_pages:Math.min(Number(raw.lookalike_pages ?? 3),10),
  exa_results_per_seed:Math.min(Number(raw.exa_results_per_seed ?? 25),100),
  parallel_match_limit:Math.min(Number(raw.parallel_match_limit ?? 150),500),
  smartlead_campaign_id:raw.smartlead_campaign_id ?? null,
  review_webhook_url:raw.review_webhook_url ?? ''
}}];

const cfg=$('Expand Seed Companies').item.json;
const results=$json.results ?? [];
if(!results.length) return [{json:{...cfg.seed,source:'seed',known_fit:true,industry:'',keywords:[],description:'',cfg}}];
return results.map((r)=>{const c=r.company ?? r; return {json:{name:c.name ?? cfg.seed.name,domain:String(c.domain ?? c.website ?? cfg.seed.domain).toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0],industry:c.industry ?? '',keywords:Array.isArray(c.keywords)?c.keywords:[],description:c.description ?? '',source:'seed+prospeo',known_fit:true,cfg}};});

const cfg=$json;
const out=[];
for(let page=1;page<=cfg.lookalike_pages;page++) out.push({json:{...cfg,page}});
return out;

const excluded=new Set($('Normalize and Validate Intake').first().json.excluded_domains);
const seen=new Set(); const out=[];
for(const item of $input.all()){
 const c=item.json; const d=String(c.domain ?? '').toLowerCase();
 if(!d||excluded.has(d)||seen.has(d)) continue;
 seen.add(d); out.push({json:c});
}
return out;

const c=$('Deduplicate Initial Candidates').item.json;
const html=typeof $json==='string'?$json:($json.data ?? $json.body ?? '');
const text=String(html).replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&[a-z#0-9]+;/gi,' ').replace(/\s+/g,' ').trim().slice(0,5000);
const cfg=c.cfg ?? $('Normalize and Validate Intake').first().json;
return [{json:{candidate:{...c,website_text:text},request_body:{model:$env.OPENAI_ICP_MODEL || 'gpt-5-nano',messages:[{role:'system',content:'You are a strict B2B company qualification engine. Return JSON only: {"qualified":boolean,"confidence":0-100,"reason":"one sentence"}.'},{role:'user',content:'ICP: '+JSON.stringify(cfg.icp)+'\nCompany: '+JSON.stringify({name:c.name,domain:c.domain,industry:c.industry,keywords:c.keywords,description:c.description})+'\nLive website text: '+text+'\nDoes this company fit?'}],response_format:{type:'json_object'},reasoning_effort:'minimal'}}}];

const src=$('Prepare Initial ICP Judge').item.json;
let decision={qualified:false,confidence:0,reason:'No model decision'};
try{decision=JSON.parse($json.choices?.[0]?.message?.content ?? '{}');}catch{}
if(src.candidate.known_fit) decision={qualified:true,confidence:100,reason:'Supplied best-fit seed company'};
return [{json:{...src.candidate,...decision}}];

const rows=$input.all().map((i)=>i.json);
if(!rows.length) throw new Error('No confirmed fits. Stop and fix the ICP or seed list.');
const cfg=$('Normalize and Validate Intake').first().json;
const evidence=rows.slice(0,150).map((c)=>({name:c.name,domain:c.domain,industry:c.industry,keywords:c.keywords,description:c.description,website_text:String(c.website_text ?? '').slice(0,1200)}));
return [{json:{confirmed:rows,cfg,request_body:{model:$env.OPENAI_ICP_MODEL || 'gpt-5-nano',messages:[{role:'system',content:'Mine database filters from confirmed ICP-fit companies. Return JSON only: {"industries":["..."],"keywords":["..."]}. Keep every observed industry. Keep discriminative product, service, customer, and category phrases. Remove generic stopwords.'},{role:'user',content:'ICP: '+JSON.stringify(cfg.icp)+'\nConfirmed fits: '+JSON.stringify(evidence)}],response_format:{type:'json_object'},reasoning_effort:'minimal'}}}];

const src=$('Prepare Filter Mining').item.json;
let plan={industries:[],keywords:[]}; try{plan=JSON.parse($json.choices?.[0]?.message?.content ?? '{}');}catch{}
const inds=[...new Set([...(plan.industries ?? []),...src.confirmed.map((c)=>c.industry).filter(Boolean)])];
const kws=[...new Set([...(plan.keywords ?? []),...src.confirmed.flatMap((c)=>Array.isArray(c.keywords)?c.keywords:[])])].filter((x)=>String(x).trim().length>2);
const base={...((src.cfg.geography)?{company_location_search:{include:[src.cfg.geography]}}:{}),company_headcount_custom:{min:src.cfg.employee_min,max:src.cfg.employee_max}};
return [...inds.map((v)=>({json:{label:'industry:'+v,filters:{...base,company_industry:{include:[v]}},cfg:src.cfg}})),...kws.map((v)=>({json:{label:'keyword:'+v,filters:{...base,company_keywords:{include:[v]}},cfg:src.cfg}}))];

const task=$('Create Filter Tasks').item.json;
const total=Number($json.pagination?.total_count ?? 0);
return [{json:{...task,total_count:total,needs_shard:total>24000}}];

const task=$json;
const cfg=task.cfg;
if(String(cfg.geography).toLowerCase().includes('united states')){
 const states=['Alabama','Alaska','Arizona','Arkansas','California','Colorado','Connecticut','Delaware','District of Columbia','Florida','Georgia','Hawaii','Idaho','Illinois','Indiana','Iowa','Kansas','Kentucky','Louisiana','Maine','Maryland','Massachusetts','Michigan','Minnesota','Mississippi','Missouri','Montana','Nebraska','Nevada','New Hampshire','New Jersey','New Mexico','New York','North Carolina','North Dakota','Ohio','Oklahoma','Oregon','Pennsylvania','Rhode Island','South Carolina','South Dakota','Tennessee','Texas','Utah','Vermont','Virginia','Washington','West Virginia','Wisconsin','Wyoming'];
 return states.map((state)=>({json:{...task,label:task.label+'|'+state,filters:{...task.filters,company_location_search:{include:[state+', United States']}}}}));
}
const min=cfg.employee_min,max=cfg.employee_max;
const edges=[min,11,51,201,501,1001,5001,10001,max+1].filter((v,i,a)=>v>=min&&v<=max+1&&a.indexOf(v)===i).sort((a,b)=>a-b);
const out=[]; for(let i=0;i<edges.length-1;i++) out.push({json:{...task,label:task.label+'|employees '+edges[i]+'-'+(edges[i+1]-1),filters:{...task.filters,company_headcount_custom:{min:edges[i],max:edges[i+1]-1}}}});
return out;

const task=$('Split Large Filters').item.json; const total=Number($json.pagination?.total_count ?? 0);
if(total>24000) throw new Error('Shard still exceeds Prospeo limit: '+task.label+' ('+total+'). Add a second shard dimension before running.');
const pages=Math.ceil(total/25); const out=[]; for(let page=1;page<=pages;page++) out.push({json:{...task,page,total_count:total}}); return out;

const c=$('Deduplicate Company Universe').item.json;
const html=typeof $json==='string'?$json:($json.data ?? $json.body ?? '');
const text=String(html).replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&[a-z#0-9]+;/gi,' ').replace(/\s+/g,' ').trim().slice(0,6000);
const parked=['domain is parked','buy this domain','domain for sale','account suspended','coming soon','under construction'].some((p)=>text.toLowerCase().includes(p));
return [{json:{candidate:{...c,website_text:text,website_status:!text?'dead':parked?'parked':'live'},request_body:{model:$env.OPENAI_ICP_MODEL || 'gpt-5-nano',messages:[{role:'system',content:'You are the final strict B2B company verifier. Return JSON only: {"qualified":boolean,"confidence":0-100,"reason":"one sentence","evidence":"short exact evidence from the supplied website text"}.'},{role:'user',content:'ICP: '+JSON.stringify(c.cfg.icp)+'\nCompany: '+c.name+' ('+c.domain+')\nCurrent website text: '+text+'\nDoes the current company fit?'}],response_format:{type:'json_object'},reasoning_effort:'minimal'}}}];

const src=$('Prepare Final Website Judge').item.json; let d={qualified:false,confidence:0,reason:'No decision',evidence:''};try{d=JSON.parse($json.choices?.[0]?.message?.content ?? '{}');}catch{}
if(src.candidate.website_status!=='live') d={qualified:false,confidence:100,reason:'Website is '+src.candidate.website_status,evidence:''};
return [{json:{...src.candidate,final_qualified:!!d.qualified,final_confidence:Number(d.confidence??0),final_reason:d.reason??'',evidence:d.evidence??'',evidence_url:'https://'+src.candidate.domain}}];
